CREATE TABLE IF NOT EXISTS sa_tenants(company TEXT PRIMARY KEY,namespace TEXT UNIQUE NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,workflow_limit INTEGER NOT NULL DEFAULT 30,active_limit INTEGER NOT NULL DEFAULT 3);
CREATE TABLE IF NOT EXISTS sa_drafts(id TEXT PRIMARY KEY,company TEXT NOT NULL,room TEXT NOT NULL,bot TEXT,actor TEXT NOT NULL,binding TEXT NOT NULL,name TEXT NOT NULL,revision INTEGER NOT NULL,configuration TEXT NOT NULL,test_hash TEXT,state TEXT NOT NULL,created REAL NOT NULL,updated REAL NOT NULL);
CREATE INDEX IF NOT EXISTS sa_drafts_scope ON sa_drafts(company,room);
CREATE TABLE IF NOT EXISTS sa_versions(workflow TEXT NOT NULL,version INTEGER NOT NULL,company TEXT NOT NULL,ir TEXT NOT NULL,hash TEXT NOT NULL,created REAL NOT NULL,PRIMARY KEY(workflow,version));
CREATE TABLE IF NOT EXISTS sa_workflows(id TEXT PRIMARY KEY,company TEXT NOT NULL,draft TEXT NOT NULL,room TEXT NOT NULL,bot TEXT,actor TEXT NOT NULL,binding TEXT NOT NULL,name TEXT NOT NULL,version INTEGER NOT NULL,state TEXT NOT NULL,engine_id TEXT UNIQUE,engine_path TEXT UNIQUE,revision INTEGER NOT NULL,created REAL NOT NULL,updated REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sa_executions(id TEXT PRIMARY KEY,company TEXT NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL,event_key TEXT NOT NULL,input_hash TEXT NOT NULL,input TEXT NOT NULL,state TEXT NOT NULL,engine_execution TEXT,approval TEXT,receipt TEXT,error TEXT,created REAL NOT NULL,updated REAL NOT NULL,UNIQUE(company,workflow,event_key));
CREATE TABLE IF NOT EXISTS sa_operations(id TEXT PRIMARY KEY,company TEXT NOT NULL,execution TEXT NOT NULL,kind TEXT NOT NULL,hash TEXT NOT NULL,state TEXT NOT NULL,result TEXT,error TEXT,created REAL NOT NULL,updated REAL NOT NULL,UNIQUE(company,execution,kind));
CREATE TABLE IF NOT EXISTS sa_approvals(id TEXT PRIMARY KEY,company TEXT NOT NULL,room TEXT NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL,execution TEXT UNIQUE NOT NULL,bot TEXT,approver TEXT NOT NULL,binding TEXT NOT NULL,parameters TEXT NOT NULL,hash TEXT NOT NULL,state TEXT NOT NULL,decision TEXT,origin TEXT,created REAL NOT NULL,expires REAL NOT NULL,decided REAL);
CREATE TABLE IF NOT EXISTS sa_authorizations(id TEXT PRIMARY KEY,company TEXT NOT NULL,execution TEXT NOT NULL,approval TEXT UNIQUE NOT NULL,hash TEXT NOT NULL,decision TEXT NOT NULL,expires REAL NOT NULL,consumed REAL);
CREATE TABLE IF NOT EXISTS sa_connections(id TEXT PRIMARY KEY,company TEXT NOT NULL,provider TEXT NOT NULL,account TEXT NOT NULL,name TEXT NOT NULL,scopes TEXT NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL,secret BLOB,expires REAL,created_by TEXT NOT NULL,created REAL NOT NULL,updated REAL NOT NULL,UNIQUE(company,provider,account));
CREATE TABLE IF NOT EXISTS sa_oauth(state_hash TEXT PRIMARY KEY,company TEXT NOT NULL,actor TEXT NOT NULL,binding TEXT NOT NULL,provider TEXT NOT NULL,room TEXT NOT NULL,draft TEXT,account_hint TEXT,verifier BLOB,expires REAL NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sa_schedules(id TEXT PRIMARY KEY,company TEXT NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL,next REAL NOT NULL,interval INTEGER NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sa_webhooks(token_hash TEXT PRIMARY KEY,company TEXT NOT NULL,workflow TEXT NOT NULL,provider TEXT NOT NULL,secret BLOB,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sa_replays(kind TEXT NOT NULL,key TEXT NOT NULL,created REAL NOT NULL,PRIMARY KEY(kind,key));
CREATE TABLE IF NOT EXISTS sa_slack_members(company TEXT NOT NULL,workspace TEXT NOT NULL,slack_user TEXT NOT NULL,user TEXT NOT NULL,binding TEXT NOT NULL,PRIMARY KEY(company,workspace,slack_user));
CREATE TABLE IF NOT EXISTS sa_notifications(id TEXT PRIMARY KEY,company TEXT NOT NULL,room TEXT NOT NULL,user TEXT NOT NULL,binding TEXT NOT NULL,approval TEXT NOT NULL,channel TEXT NOT NULL,state TEXT NOT NULL,created REAL NOT NULL,UNIQUE(approval,channel));
CREATE TABLE IF NOT EXISTS sa_audit(id TEXT PRIMARY KEY,company TEXT NOT NULL,actor TEXT NOT NULL,kind TEXT NOT NULL,resource TEXT NOT NULL,detail TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sa_jobs(id TEXT PRIMARY KEY,company TEXT NOT NULL,execution TEXT NOT NULL,kind TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next REAL NOT NULL,error TEXT,UNIQUE(execution,kind));
CREATE TABLE IF NOT EXISTS sa_grants(workflow TEXT PRIMARY KEY,company TEXT NOT NULL,version INTEGER NOT NULL,actor TEXT NOT NULL,binding TEXT NOT NULL,hash TEXT NOT NULL,state TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sa_engine_resources(company TEXT NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL,engine_id TEXT UNIQUE NOT NULL,path TEXT UNIQUE NOT NULL,state TEXT NOT NULL,PRIMARY KEY(workflow,version));
CREATE TABLE IF NOT EXISTS sa_schedule_events(schedule TEXT PRIMARY KEY,company TEXT NOT NULL,input TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sa_scheduled_fires(id TEXT PRIMARY KEY,company TEXT NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL,schedule TEXT NOT NULL,slot REAL NOT NULL,input TEXT NOT NULL,state TEXT NOT NULL,UNIQUE(schedule,slot));
CREATE TABLE IF NOT EXISTS sa_schema_versions(version INTEGER PRIMARY KEY,applied TEXT NOT NULL);
INSERT OR IGNORE INTO sa_schema_versions VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS sa_origins(kind TEXT NOT NULL,resource TEXT NOT NULL,version INTEGER NOT NULL,company TEXT NOT NULL,room TEXT NOT NULL,bot TEXT NOT NULL,source_assistant TEXT NOT NULL,feedback_message TEXT NOT NULL,PRIMARY KEY(kind,resource,version));
CREATE TABLE IF NOT EXISTS sa_feedback_events(cursor INTEGER PRIMARY KEY AUTOINCREMENT,company TEXT NOT NULL,room TEXT NOT NULL,kind TEXT NOT NULL,resource TEXT NOT NULL,created REAL NOT NULL);
CREATE INDEX IF NOT EXISTS sa_feedback_scope ON sa_feedback_events(company,room,cursor);
INSERT OR IGNORE INTO sa_schema_versions VALUES(2,datetime('now'));
CREATE TABLE IF NOT EXISTS sa_internal_receipts(id TEXT PRIMARY KEY,company TEXT NOT NULL,execution TEXT UNIQUE NOT NULL,version INTEGER NOT NULL,approval TEXT NOT NULL,engine_execution TEXT NOT NULL,created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS sa_provider_settings(company TEXT NOT NULL,provider TEXT NOT NULL,account TEXT NOT NULL,revision INTEGER NOT NULL,created_by TEXT NOT NULL,updated REAL NOT NULL,PRIMARY KEY(company,provider));
CREATE TABLE IF NOT EXISTS sa_oauth_handoffs(hash TEXT PRIMARY KEY,state_hash TEXT UNIQUE NOT NULL,company TEXT NOT NULL,actor TEXT NOT NULL,binding TEXT NOT NULL,provider TEXT NOT NULL,secret BLOB,expires REAL NOT NULL,state TEXT NOT NULL);
INSERT OR IGNORE INTO sa_schema_versions VALUES(3,datetime('now'));
CREATE TABLE IF NOT EXISTS sa_integration_cards(company TEXT NOT NULL,room TEXT NOT NULL,message TEXT NOT NULL,bot TEXT NOT NULL,provider TEXT NOT NULL,updated REAL NOT NULL,PRIMARY KEY(company,message,provider));
